    "path_warrior_desc": "Trenuje Walkę, kupuje broń i zbroje. Poluje na zwierzynę (U1), potwory (U2) i pokonuje 2 smoki królestwa (U3) dla natychmiastowego triumfu bez konieczności zbierania serc!",
    "path_breeder_title": "🐎 Hodowca & Ziemianin",
    "path_breeder_desc": "Wykupuje zwierzęta z tego samego zestawu (Koń, Pies, Sokół) dla 80% czynszu, buduje stajnie ze stadami gospodarskimi i podnosi wioski do potężnych twierdz.",
    "path_courtier_title": "👑 Dworzanin & Dyplomata",
    "path_courtier_desc": "Trenuje Taniec i Charyzmę, bywa na zamkowych balach i festynach. Przy każdej wizycie na Starcie otrzymuje audiencję i mnoży zyski serc!",
