    "path_warrior_header": "⚔️ 1. Droga Wojownika",
    "path_warrior_points": "• Inwestuj w cnotę <strong>Walki</strong>, kuźnie i broń.<br/>• Wykonuj zadania na potwory U1–U2 i dominuj w <strong>Turniejach</strong>.<br/>• <strong>Smoczy triumf:</strong> Pokonanie 2 smoków natychmiast wygrywa grę bez względu na liczbę serc!",
    "path_breeder_header": "🐎 2. Droga Hodowcy",
    "path_breeder_points": "• Kupuj trójki zwierząt (koń + pies + sokół) dla premii <strong>+1,5 💖</strong>.<br/>• Nabywaj stada gospodarskie w stajniach (owce, świnie, bydło).<br/>• Utrzymuj 1. miejsce w <strong>Premii Hodowlanej (+4,0 💖)</strong> i wygrywaj Wielkie Gonitwy.",
    "path_diplomat_header": "💃 3. Droga Dyplomaty",
    "path_diplomat_points": "• Inwestuj w <strong>Taniec, Charyzmę i stroje balowe</strong>.<br/>• Audiencja u króla na Starcie i Zamku (<strong>+0,5 do +1,0 💖</strong>).<br/>• Wygrywaj na <strong>Balach Zamkowych</strong> (aż do +5 💖 i 1 200 zł. za zwycięstwo).",
