    "epilogue_dragon": "Jako legendarny pogromca smoków złożył smoczy łeb u stóp księżniczki. Królowa zawiesiła mu na szyi rubinowy naszyjnik, a całe królestwo świętowało powrót bohatera.",
    "epilogue_estates": "Jako najpotężniejszy namiestnik włości i hodowli stworzył kwitnące imperium od wiosek po warowne zamki. Królewski dwór powierzył mu rękę księżniczki i pieczęć tronu.",
